edits.after_source:
page {
  background-color: #f5f5f5;
  font-size: 28rpx;
  color: #333;
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI",
    "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
}

edits.before_source:
.goods-card {
  width: 48%;
  background: #fff;
  border-radius: 12rpx;
  margin-bottom: 20rpx;
  overflow: hidden;
}

edits.after_source:
.goods-card {
  width: 48%;
  background: #fff;
  border-radius: 20rpx;
  margin-bottom: 20rpx;
  overflow: hidden;
}

.price {
  font-family: "CinaShop DIN", "PingFang SC", -apple-system, BlinkMacSystemFont,
    "Segoe UI", "Microsoft YaHei", sans-serif;
  color: var(--view-priceColor, #e93323);
  font-size: 32rpx;
  font-weight: 600;
}
